def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    stage = nb.get('stage') or 'start'
    if p.get('unknown_column_error') or p.get('syntax_error') or s.get('last_error_kind') in ('unknown_col', 'syntax'):
        stage = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
    elif p.get('last_result_empty') and not p.get('mutation_task'):
        stage = 'fixing_empty_result'
    elif p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        stage = 'repeated_query_loop'
    elif p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        stage = 'text_numeric_handling'
    elif p.get('mutation_task') and p.get('mutation_not_attempted'):
        stage = 'mutation_needs_execution'
    elif p.get('mutation_task') and s.get('mutation_attempted'):
        stage = 'ready_to_commit_candidate'
    if p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        nb['candidate_available'] = True
    if p.get('remaining_rounds_low'):
        nb['low_rounds'] = True
    nb['stage'] = stage
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Schema or identifier issue: use SHOW TABLES, then DESCRIBE the exact table name. In MySQL, wrap table and column identifiers containing spaces, punctuation, or reserved words in backticks, not double quotes.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT: inspect sample rows and DISTINCT values for the filtered columns. TEXT fields may store years, dates, ranks, or numbers as strings, so use LIKE, TRIM, or CAST instead of exact equality when appropriate.'
    elif stage == 'repeated_query_loop':
        msg = 'Repeated SQL is not adding evidence. Change strategy: inspect schema, sample rows, distinct values, or relax one predicate at a time before trying another filter.'
    elif stage == 'text_numeric_handling':
        msg = 'TEXT numerics: for ordering, ranking, or aggregation, clean separators such as commas or percent signs and CAST to SIGNED or DECIMAL; do not rely on lexicographic text order.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: first execute the INSERT, UPDATE, or DELETE with exact requested literals and backticked identifiers. An empty tool result can still mean the data-changing statement ran.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Mutation verification: run a SELECT that checks the affected row or count. If the database state matches the request, commit a brief confirmation; do not treat [] after a mutation as failure.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def hook(ctx, nb):
    a = ctx.get('action') or {}
    p = ctx.get('predicates') or {}
    if a.get('tool') != 'commit_final_answer':
        return None
    if p.get('commit_before_sql') or p.get('no_sql_yet'):
        return {'kind': 'block_and_prompt', 'message': 'Run at least one SQL query to inspect or modify the database before committing a final answer.'}
    if p.get('commit_empty_answer') and not (p.get('mutation_task') and (nb.get('stage') == 'ready_to_commit_candidate' or (ctx.get('state') or {}).get('mutation_attempted'))):
        return {'kind': 'block_and_prompt', 'message': 'Do not commit an empty answer for a SELECT-style task. Use SQL evidence to provide the requested value or values.'}
    if p.get('mutation_task') and p.get('mutation_not_attempted'):
        return {'kind': 'block_and_prompt', 'message': 'This is a data-changing task. Execute the INSERT, UPDATE, or DELETE first, then verify the affected rows before committing.'}
    return None
